const fs = require("fs");
const { spawn } = require("child_process");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const dir = "/tmp/proj";
fs.mkdirSync(dir, { recursive: true });
fs.writeFileSync(dir + "/index.js", "export default { fetch() { return new Response('ok'); } };\n");
fs.writeFileSync(dir + "/wrangler.json", JSON.stringify({ name: "demo", main: "index.js" }));
const pad = (n) => String(n).padStart(2, "0");
const now = new Date();
const today = new Set([
  now.getFullYear() + "-" + pad(now.getMonth() + 1) + "-" + pad(now.getDate()),
  now.getUTCFullYear() + "-" + pad(now.getUTCMonth() + 1) + "-" + pad(now.getUTCDate()),
]);
const child = spawn(process.execPath, ["/w/node_modules/wrangler/bin/wrangler.js", "dev", "--port", "8787", "--inspector-port", "9229"], {
  cwd: dir,
  detached: true,
  stdio: ["ignore", "pipe", "pipe"],
  env: { ...process.env, WRANGLER_SEND_METRICS: "false", NO_COLOR: "1", FORCE_COLOR: "0" },
});
let out = "";
let done = false;
function stop() { try { process.kill(-child.pid, "SIGKILL"); } catch (e) { try { child.kill("SIGKILL"); } catch (e2) {} } }
function check() {
  if (done) return;
  const clean = out.replace(/\x1b\[[0-9;]*m/g, "");
  const m = clean.match(/No compatibility_date was specified\. Using [^:]*: (\d{4}-\d{2}-\d{2})/);
  if (!m) return;
  done = true;
  stop();
  const date = m[1];
  if (today.has(date)) { console.log("got " + date); symptom("with no compatibility_date, wrangler dev used today's date"); }
  if (!(date < [...today].sort()[0])) broken("unexpected default compatibility date " + date);
  console.log("OK: with no compatibility_date, wrangler dev used the fixed default " + date);
  process.exit(0);
}
child.stdout.on("data", (d) => { out += d; check(); });
child.stderr.on("data", (d) => { out += d; check(); });
child.on("exit", () => { setTimeout(() => { if (!done) { check(); if (!done) broken("wrangler dev exited without the compatibility date warning: " + out.slice(-800)); } }, 200); });
setTimeout(() => { if (!done) { stop(); broken("timed out waiting for the compatibility date warning: " + out.slice(-800)); } }, 75000);

